91	  return Hny.inSpanAsync("mtg-deck-shuffler-web", "copy card to clipboard", async (span) => {
92	    const proxyUrl = `/proxy-image?cardId=${encodeURIComponent(cardId)}&face=${encodeURIComponent(face)}`;
93	    const response = await fetch(proxyUrl);
94	    span?.setAttribute("app.response.ok", response.ok);
95	    if (response.ok) {
96	      const blob = await response.blob();
97	      span?.setAttribute("app.blob.type", blob.type);
98	      span?.setAttribute("app.blob.size", blob.size);
99	      await navigator.clipboard.write([
100	        new ClipboardItem({
101	          [blob.type]: blob,
102	        }),
103	      ]);
104	      return true;
105	    }
106	    return false;
107	  });
108	}
